INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT156-S2-Q4$batch13$, 156, 2, 4, $batch13$Role$batch13$, $batch13$Business writer: Although the demand for Corinne wristwatches currently far outstrips supply, it would be a mistake for the manufacturer to increase supply to meet demand. The current demand results from the public's perception that the wristwatches are in short supply, and the wristwatches are in short supply merely because they are produced in very limited quantities. The excess demand creates the impression that the wristwatches are greatly desired, and that impression in turn helps account for consumers' desire for them. If the supply of Corinne wristwatches were to increase to meet demand, excess demand for them would be eliminated, with the result that the wristwatches would no longer be desired.$batch13$, $batch13$The claim that it would be a mistake for the manufacturer of Corinne wristwatches to increase supply to meet demand plays which one of the following roles in the business writer's argument?$batch13$, $batch13$E$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$an introductory claim that describes the position to be refuted by the argument$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$a justification of the relevance of the evidence cited$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$a premise of the argument$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$an opinion offered in support of one of the argument's premises$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$the conclusion toward which the argument is directed$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$It would be a mistake for the manufacturer to increase supply to meet demand.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Demand comes from the perception that the watches are scarce, and they're scarce only because few are made. Excess demand makes the watches seem desirable, which fuels the desire for them. If supply met demand, the excess would vanish and the watches would no longer be desired.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$"Although demand far outstrips supply" is a concession. The author's claim follows it. Every later sentence explains why raising supply would backfire, so they all support the first claim.$batch13$), (3, $batch13$Goal$batch13$, $batch13$The claim is the conclusion.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The argument defends this claim. The "although" clause is the point it pushes against.$batch13$), ($batch13$B$batch13$, $batch13$It doesn't justify the relevance of any evidence. It's what the evidence supports.$batch13$), ($batch13$C$batch13$, $batch13$It's supported by every later sentence, so it isn't a premise.$batch13$), ($batch13$D$batch13$, $batch13$Nothing else rests on it. It's the top of the argument.$batch13$), ($batch13$E$batch13$, $batch13$The rest of the passage explains why increasing supply would be a mistake.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT156-S2-Q4$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
